<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'

const voiceStore = useVoiceStore()

const isMuted = computed(() => voiceStore.state.isMuted)
const isDeafened = computed(() => voiceStore.state.isDeafened)
const volume = computed(() => voiceStore.state.volume)
const noiseSuppressionEnabled = computed(() => voiceStore.state.noiseSuppressionEnabled)
const spatialAudioEnabled = computed(() => voiceStore.state.spatialAudioEnabled)

function toggleMute() {
  voiceStore.setMuted(!isMuted.value)
}

function toggleDeafen() {
  voiceStore.setDeafened(!isDeafened.value)
}

function handleVolumeChange(event: Event) {
  const value = (event.target as HTMLInputElement).valueAsNumber
  voiceStore.setVolume(value)
}

function toggleNoiseSuppression() {
  voiceStore.setNoiseSuppressionEnabled(!noiseSuppressionEnabled.value)
}

function toggleSpatialAudio() {
  voiceStore.setSpatialAudioEnabled(!spatialAudioEnabled.value)
}
</script>

<template>
  <div class="voice-controls">
    <div class="control-group main-controls">
      <button
        @click="toggleMute"
        class="control-btn large"
        :class="{ active: isMuted, 'btn-danger': isMuted }"
        :aria-pressed="isMuted"
        aria-label="Mikrofon stummschalten"
      >
        <svg v-if="!isMuted" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
          <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
          <line x1="12" y1="19" x2="12" y2="22" />
          <line x1="8" y1="19" x2="8" y2="22" />
          <line x1="16" y1="19" x2="16" y2="22" />
        </svg>
        <svg v-else width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M9 9v3M5 13l5 5 5-5" />
          <line x1="17" y1="9" x2="12" y2="14" />
          <line x1="15" y1="5" x2="9" y2="9" />
        </svg>
        <span class="control-label">{{ isMuted ? 'Stumm' : 'Mikrofon' }}</span>
      </button>
      
      <button
        @click="toggleDeafen"
        class="control-btn large"
        :class="{ active: isDeafened, 'btn-warning': isDeafened }"
        :aria-pressed="isDeafened"
        aria-label="Audio deaktivieren"
      >
        <svg v-if="!isDeafened" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
          <line x1="12" y1="19" x2="12" y2="22" />
          <line x1="8" y1="19" x2="8" y2="22" />
          <line x1="16" y1="19" x2="16" y2="22" />
        </svg>
        <svg v-else width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
          <line x1="12" y1="19" x2="12" y2="22" />
          <line x1="8" y1="19" x2="8" y2="22" />
          <line x1="16" y1="19" x2="16" y2="22" />
          <line x1="2" y1="2" x2="22" y2="22" />
        </svg>
        <span class="control-label">{{ isDeafened ? 'Taub' : 'Audio' }}</span>
      </button>
    </div>
    
    <div class="control-group volume-control">
      <label class="volume-label">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" />
          <path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07" />
        </svg>
        <span>Lautstärke</span>
      </label>
      <input
        type="range"
        min="0"
        max="1"
        step="0.01"
        :value="volume"
        @input="handleVolumeChange"
        class="volume-slider"
        aria-label="Ausgabe-Lautstärke"
      >
      <span class="volume-value">{{ Math.round(volume * 100) }}%</span>
    </div>
    
    <div class="control-group feature-toggles">
      <button
        @click="toggleNoiseSuppression"
        class="control-btn toggle"
        :class="{ active: noiseSuppressionEnabled }"
        :aria-pressed="noiseSuppressionEnabled"
        aria-label="Rauschunterdrückung"
      >
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M12 2a10 10 0 0 1 10 10c0 1.5-.3 2.9-.8 4.2" />
          <path d="M2 12a10 10 0 0 1 10-10c1.5 0 2.9.3 4.2.8" />
          <line x1="2" y1="2" x2="22" y2="22" />
        </svg>
        <span>RNNoise</span>
      </button>
      
      <button
        @click="toggleSpatialAudio"
        class="control-btn toggle"
        :class="{ active: spatialAudioEnabled }"
        :aria-pressed="spatialAudioEnabled"
        aria-label="3D-Audio"
      >
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <circle cx="12" cy="12" r="10" />
          <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
        </svg>
        <span>3D-Audio</span>
      </button>
    </div>
  </div>
</template>

