<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed, watch } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'

const voiceStore = useVoiceStore()

const canvasRef = ref<HTMLCanvasElement | null>(null)
const animationFrameId = ref<number | null>(null)
const audioContext = ref<AudioContext | null>(null)
const analyser = ref<AnalyserNode | null>(null)
const dataArray = ref<Uint8Array>(new Uint8Array(0))

const isAnalyzing = computed(() => voiceStore.state.localStream !== null)

const micLevel = computed(() => {
  if (dataArray.value.length === 0) return 0
  const sum = dataArray.value.reduce((a, b) => a + b, 0)
  return (sum / dataArray.value.length / 255) * 100
})

const barCount = 64
const barWidth = 4
const barGap = 2

function initAudioAnalysis() {
  if (!voiceStore.state.localStream) return
  
  try {
    audioContext.value = new AudioContext({ latencyHint: 'interactive' })
    analyser.value = audioContext.value.createAnalyser()
    analyser.value.fftSize = 256
    analyser.value.smoothingTimeConstant = 0.8
    
    const source = audioContext.value.createMediaStreamSource(voiceStore.state.localStream)
    source.connect(analyser.value)
    
    dataArray.value = new Uint8Array(analyser.value!.frequencyBinCount)
    
    animate()
  } catch (err) {
    console.error('Audio visualizer init error:', err)
  }
}

function animate() {
  if (!analyser.value || !dataArray.value || !canvasRef.value) return

  const canvas = canvasRef.value!
  const ctx = canvas.getContext('2d')!

  const dpr = window.devicePixelRatio || 1
  const width = canvas.clientWidth
  const height = canvas.clientHeight

  canvas.width = width * dpr
  canvas.height = height * dpr
  ctx.scale(dpr, dpr)

  analyser.value.getByteFrequencyData(dataArray.value as unknown as Uint8Array<ArrayBuffer>)

  ctx.clearRect(0, 0, width, height)
  
  const centerX = width / 2
  const maxBarHeight = height * 0.4
  
  for (let i = 0; i < barCount; i++) {
    const dataIndex = Math.floor((i / barCount) * (dataArray.value?.length ?? 0))
    const value = (dataArray.value?.[dataIndex] ?? 0) / 255
    const barHeight = value * maxBarHeight
    
    const x = centerX - (barCount * (barWidth + barGap)) / 2 + i * (barWidth + barGap)
    const y = height / 2
    
    const hue = 200 + value * 60
    ctx.fillStyle = `hsla(${hue}, 80%, 60%, ${0.5 + value * 0.5})`
    
    ctx.fillRect(x, y - barHeight / 2, barWidth, barHeight)
    ctx.fillRect(x, y + barHeight / 2, barWidth, -barHeight)
  }
  
  animationFrameId.value = requestAnimationFrame(animate)
}

function cleanup() {
  if (animationFrameId.value) {
    cancelAnimationFrame(animationFrameId.value)
    animationFrameId.value = null
  }
  if (audioContext.value) {
    audioContext.value.close()
    audioContext.value = null
  }
  analyser.value = null
  dataArray.value = new Uint8Array(0)
}

onMounted(() => {
  if (isAnalyzing.value) {
    initAudioAnalysis()
  }
})

onUnmounted(() => {
  cleanup()
})

// Watch for stream changes
watch(() => voiceStore.state.localStream, (newStream) => {
  cleanup()
  if (newStream) {
    initAudioAnalysis()
  }
})
</script>

<template>
  <div class="audio-visualizer" v-if="isAnalyzing">
    <canvas ref="canvasRef" class="visualizer-canvas" aria-label="Audio-Visualisierung" />
    <div class="visualizer-overlay">
      <span class="visualizer-label">Dein Mikrofon</span>
      <div class="level-indicator" :style="{ width: `${micLevel}%` }" />
    </div>
  </div>
  <div v-else class="audio-visualizer placeholder">
    <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="opacity: 0.3;">
      <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
      <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
      <line x1="12" y1="19" x2="12" y2="22" />
      <line x1="8" y1="19" x2="8" y2="22" />
      <line x1="16" y1="19" x2="16" y2="22" />
    </svg>
    <p>Kein Mikrofon aktiv</p>
  </div>
</template>

